using ProMaxx2.QA.Application.Common;using ProMaxx2.QA.Domain.Requirements;using ProMaxx2.QA.Application.Projects;
namespace ProMaxx2.QA.Application.Requirements;
public sealed record RequirementDto(Guid RequirementId,Guid ProjectId,Guid? ReleaseId,Guid ModuleId,string RequirementCode,string Title,string? Description,string? AcceptanceCriteria,string Priority,string? RiskLevel,string? Source,Guid? OwnerUserId,string Status,int RevisionNo,bool IsInScope,DateTime CreatedAt);public sealed record RequirementRevisionDto(int RevisionNo,string Title,string?Description,string?AcceptanceCriteria,Guid?ChangedBy,DateTime ChangedAt,string?ChangeReason);
public sealed record CreateRequirementRequest(Guid ProjectId,Guid?ReleaseId,Guid ModuleId,string RequirementCode,string Title,string?Description,string?AcceptanceCriteria,string Priority,string?RiskLevel,string?Source,Guid?OwnerUserId,bool IsInScope=true);public sealed record UpdateRequirementRequest(Guid?ReleaseId,Guid ModuleId,string Title,string?Description,string?AcceptanceCriteria,string Priority,string?RiskLevel,string?Source,Guid?OwnerUserId,bool IsInScope);public sealed record CreateRevisionRequest(string Title,string?Description,string?AcceptanceCriteria,string ChangeReason);public sealed record ChangeRequirementStatusRequest(string Status);
public sealed record RequirementFilter(Guid?ProjectId,Guid?ReleaseId,Guid?ModuleId,string?Status,string?Priority,bool?InScope,string?Search);
public interface IRequirementRepository{Task<IReadOnlyList<RequirementDto>>ListAsync(RequirementFilter filter,CancellationToken ct);Task<RequirementDto?>GetAsync(Guid id,CancellationToken ct);Task<Requirement?>FindAsync(Guid id,CancellationToken ct);Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct);Task AddAsync(Requirement entity,CancellationToken ct);void AddRevision(RequirementRevision revision);Task<IReadOnlyList<RequirementRevisionDto>>RevisionsAsync(Guid id,CancellationToken ct);Task SaveAsync(CancellationToken ct);}
public sealed class RequirementService(IRequirementRepository repository){private readonly IProjectRepository? projectRepository;public RequirementService(IRequirementRepository repository,IProjectRepository? projectRepository):this(repository){this.projectRepository=projectRepository;}public Task<IReadOnlyList<RequirementDto>>ListAsync(RequirementFilter f,CancellationToken ct)=>repository.ListAsync(f,ct);public async Task<RequirementDto>GetAsync(Guid id,CancellationToken ct)=>await repository.GetAsync(id,ct)??throw new EntityNotFoundException("Requirement not found.");public async Task<RequirementDto>CreateAsync(CreateRequirementRequest r,Guid?userId,CancellationToken ct){var code=await ResolveCodeAsync(r,ct);if(await repository.CodeExistsAsync(r.ProjectId,code,ct))throw new DuplicateCodeException("Requirement code already exists.");var e=new Requirement(r.ProjectId,r.ReleaseId,r.ModuleId,code,r.Title,r.Description,r.AcceptanceCriteria,r.Priority,r.RiskLevel,r.Source,r.OwnerUserId,r.IsInScope,userId);await repository.AddAsync(e,ct);await repository.SaveAsync(ct);return(await repository.GetAsync(e.RequirementId,ct))!;}public async Task<RequirementDto>UpdateAsync(Guid id,UpdateRequirementRequest r,Guid?userId,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Requirement not found.");e.Update(r.ReleaseId,r.ModuleId,r.Title,r.Description,r.AcceptanceCriteria,r.Priority,r.RiskLevel,r.Source,r.OwnerUserId,r.IsInScope,userId);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task<RequirementDto>ReviseAsync(Guid id,CreateRevisionRequest r,Guid?userId,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Requirement not found.");e.CreateRevision(r.Title,r.Description,r.AcceptanceCriteria,r.ChangeReason,userId);repository.AddRevision(e.Revisions.OrderByDescending(x=>x.RevisionNo).First());await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public Task<IReadOnlyList<RequirementRevisionDto>>RevisionsAsync(Guid id,CancellationToken ct)=>repository.RevisionsAsync(id,ct);public async Task<RequirementDto>StatusAsync(Guid id,string status,Guid?userId,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Requirement not found.");e.ChangeStatus(status,userId);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task DeleteAsync(Guid id,Guid?userId,CancellationToken ct){var e=await repository.FindAsync(id,ct)??throw new EntityNotFoundException("Requirement not found.");e.SoftDelete(userId);await repository.SaveAsync(ct);}private async Task<string>ResolveCodeAsync(CreateRequirementRequest r,CancellationToken ct){if(!string.IsNullOrWhiteSpace(r.RequirementCode))return r.RequirementCode.Trim().ToUpperInvariant();if(projectRepository is null)throw new ArgumentException("Requirement code is required.");var project=await projectRepository.GetAsync(r.ProjectId,ct)??throw new EntityNotFoundException("Project not found.");var module=await projectRepository.FindModuleAsync(r.ModuleId,ct)??throw new EntityNotFoundException("Module not found.");if(module.ProjectId!=r.ProjectId)throw new EntityNotFoundException("Module not found.");var prefix=BusinessCodeGenerator.ContextualPrefix(project.ProjectCode,module.ModuleCode,"REQ");return await BusinessCodeGenerator.NextAvailableAsync(prefix,candidate=>repository.CodeExistsAsync(r.ProjectId,candidate,ct));}}
